private static ChunkInputStream throwingChunkInputStream(IOException ex, int len, boolean succeedOnRetry) throws IOException {
    final ChunkInputStream stream = mock(ChunkInputStream.class);
    OngoingStubbing<Integer> stubbing = when(stream.read(any(), anyInt(), anyInt())).thenThrow(ex);
    if (succeedOnRetry) {
        stubbing.thenReturn(len);
    }
    when(stream.getRemaining()).thenReturn((long) len);
    return stream;
}

private static ChunkInputStream throwingChunkInputStream(IOException ex, int len, boolean succeedOnRetry) throws IOException {
    final ChunkInputStream stream = mock(ChunkInputStream.class);
    OngoingStubbing<Integer> stubbing = when(stream.read(any(), anyInt(), anyInt())).thenThrow(ex);
    if (succeedOnRetry) {
        stubbing.thenReturn(len);
    }
    when(stream.getRemaining()).thenReturn((long) len);
    return stream;
}

@ParameterizedTest
@MethodSource("exceptionsTriggersRefresh")
public void testRefreshOnReadFailureAfterUnbuffer(IOException ex) throws Exception {
    // GIVEN
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    BlockLocationInfo blockLocationInfo = mock(BlockLocationInfo.class);
    when(clientFactory.acquireClientForReadData(pipeline)).thenReturn(client);
    final int len = 200;
    final ChunkInputStream stream = throwingChunkInputStream(ex, len, true);
    when(refreshFunction.apply(blockID)).thenReturn(blockLocationInfo);
    when(blockLocationInfo.getPipeline()).thenReturn(newPipeline);
    OzoneClientConfig clientConfig = conf.getObject(OzoneClientConfig.class);
    clientConfig.setChecksumVerify(false);
    BlockInputStream subject = new BlockInputStream(blockID, blockSize, pipeline, null, clientFactory, refreshFunction, clientConfig) {

        @Override
        protected List<ChunkInfo> getChunkInfoListUsingClient() {
            return chunks;
        }

        @Override
        protected ChunkInputStream createChunkInputStream(ChunkInfo chunkInfo) {
            return stream;
        }
    };
    try {
        subject.initialize();
        subject.unbuffer();
        // WHEN
        byte[] b = new byte[len];
        int bytesRead = subject.read(b, 0, len);
        // THEN
        assertEquals(len, bytesRead);
        verify(refreshFunction).apply(blockID);
        verify(clientFactory).acquireClientForReadData(pipeline);
        verify(clientFactory).releaseClientForReadData(client, false);
    } finally {
        subject.close();
    }
}

