private void testRefreshesPipelineOnReadFailure(IOException ex, BlockLocationInfo blockLocationInfo, Function<BlockID, BlockLocationInfo> refreshPipelineFunction) throws Exception {
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    final int len = 200;
    final ChunkInputStream stream = throwingChunkInputStream(ex, len, true);
    when(this.refreshFunction.apply(any())).thenAnswer(inv -> refreshPipelineFunction.apply(blockID));
    try (BlockInputStream subject = createSubject(blockID, blockLocationInfo.getPipeline(), stream)) {
        subject.initialize();
        // WHEN
        byte[] b = new byte[len];
        int bytesRead = subject.read(b, 0, len);
        // THEN
        assertEquals(len, bytesRead);
        verify(this.refreshFunction).apply(blockID);
    } finally {
        reset(this.refreshFunction);
    }
}

