private BlockOutputStream createBlockOutputStream(BufferPool bufferPool) throws IOException {
    final Pipeline pipeline = MockPipeline.createRatisPipeline();
    final XceiverClientManager xcm = mock(XceiverClientManager.class);
    when(xcm.acquireClient(any())).thenReturn(new MockXceiverClientSpi(pipeline));
    OzoneClientConfig config = new OzoneClientConfig();
    config.setStreamBufferSize(4 * 1024 * 1024);
    config.setStreamBufferMaxSize(32 * 1024 * 1024);
    config.setStreamBufferFlushDelay(true);
    config.setStreamBufferFlushSize(16 * 1024 * 1024);
    config.setChecksumType(ChecksumType.NONE);
    config.setBytesPerChecksum(256 * 1024);
    StreamBufferArgs streamBufferArgs = StreamBufferArgs.getDefaultStreamBufferArgs(pipeline.getReplicationConfig(), config);
    return new RatisBlockOutputStream(new BlockID(1L, 1L), xcm, pipeline, bufferPool, config, null, ContainerClientMetrics.acquire(), streamBufferArgs, () -> newFixedThreadPool(10));
}

