public void testDeleteBlocksCommandHandlerWithTimeoutFailed(ContainerTestVersionInfo versionInfo) throws Exception {
    prepareTest(versionInfo);
    assertThat(containerSet.containerCount()).isGreaterThanOrEqualTo(2);
    Iterator<Container<?>> iterator = containerSet.getContainerIterator(volume1);
    Container<?> lockedContainer = iterator.next();
    Container<?> nonLockedcontainer = iterator.next();
    DeletedBlocksTransaction transaction1 = createDeletedBlocksTransaction(1, lockedContainer.getContainerData().getContainerID());
    DeletedBlocksTransaction transaction2 = createDeletedBlocksTransaction(2, nonLockedcontainer.getContainerData().getContainerID());
    // By letting lockedContainer hold the lock and not releasing it,
    // lockedContainer's delete command processing will time out
    // and retry, but it will still fail eventually
    // nonLockedContainer will succeed because it does not hold the lock
    lockedContainer.writeLock();
    List<DeletedBlocksTransaction> transactions = Arrays.asList(transaction1, transaction2);
    List<DeleteBlockTransactionResult> results = handler.executeCmdWithRetry(transactions);
    String schemaVersionOrDefault = ((KeyValueContainerData) nonLockedcontainer.getContainerData()).getSupportedSchemaVersionOrDefault();
    verify(handler.getSchemaHandlers().get(schemaVersionOrDefault), times(1)).handle(eq((KeyValueContainerData) nonLockedcontainer.getContainerData()), eq(transaction2));
    // submitTasks will be executed twice, as if there were retries
    verify(handler, times(1)).submitTasks(eq(transactions));
    verify(handler, times(1)).submitTasks(eq(Arrays.asList(transaction1)));
    assertEquals(2, results.size());
    // Only one transaction will succeed
    Map<Long, DeleteBlockTransactionResult> resultsMap = new HashMap<>();
    results.forEach(result -> resultsMap.put(result.getTxID(), result));
    assertFalse(resultsMap.get(transaction1.getTxID()).getSuccess());
    assertTrue(resultsMap.get(transaction2.getTxID()).getSuccess());
    assertEquals(1, blockDeleteMetrics.getTotalLockTimeoutTransactionCount());
}

