private void testMixedSchemaImport(String dir, boolean schemaV3Enabled) throws IOException {
    OzoneConfiguration conf = new OzoneConfiguration();
    final String dir1 = dir + (schemaV3Enabled ? "/v3" : "/v2");
    // create HddsVolume
    HddsVolume hddsVolume1 = new HddsVolume.Builder(dir1).conf(conf).datanodeUuid(datanodeId.toString()).build();
    conf.setBoolean(CONTAINER_SCHEMA_V3_ENABLED, schemaV3Enabled);
    StorageVolumeUtil.checkVolume(hddsVolume1, scmId, scmId, conf, null, null);
    hddsVolumes.clear();
    hddsVolumes.add(hddsVolume1);
    // create container
    long containerId = 1;
    KeyValueContainerData data = new KeyValueContainerData(containerId, ContainerLayoutVersion.FILE_PER_BLOCK, ContainerTestHelper.CONTAINER_MAX_SIZE, UUID.randomUUID().toString(), UUID.randomUUID().toString());
    KeyValueContainer container = new KeyValueContainer(data, conf);
    container.create(volumeSet, volumeChoosingPolicy, scmId);
    long pendingDeleteBlockCount = 20;
    try (DBHandle meta = BlockUtils.getDB(data, conf)) {
        Table<String, Long> metadataTable = meta.getStore().getMetadataTable();
        metadataTable.put(data.getPendingDeleteBlockCountKey(), pendingDeleteBlockCount);
    }
    container.close();
    // verify container schema
    if (schemaV3Enabled) {
        assertEquals(SCHEMA_V3, container.getContainerData().getSchemaVersion());
    } else {
        assertEquals(SCHEMA_V2, container.getContainerData().getSchemaVersion());
    }
    //export container
    TarContainerPacker packer = new TarContainerPacker(NO_COMPRESSION);
    File file1 = new File(dir1 + "/" + containerId);
    if (!file1.createNewFile()) {
        fail("Failed to create file " + file1.getAbsolutePath());
    }
    try (FileOutputStream fos = new FileOutputStream(file1)) {
        container.exportContainerData(fos, packer);
    }
    // create new HddsVolume
    conf.setBoolean(CONTAINER_SCHEMA_V3_ENABLED, !schemaV3Enabled);
    final String dir2 = dir + (schemaV3Enabled ? "/v2" : "/v3");
    HddsVolume hddsVolume2 = new HddsVolume.Builder(dir2).conf(conf).datanodeUuid(datanodeId.toString()).build();
    StorageVolumeUtil.checkVolume(hddsVolume2, scmId, scmId, conf, null, null);
    hddsVolumes.clear();
    hddsVolumes.add(hddsVolume2);
    // import container to new HddsVolume
    KeyValueContainer importedContainer = new KeyValueContainer(data, conf);
    importedContainer.populatePathFields(scmId, hddsVolume2);
    try (FileInputStream fio = new FileInputStream(file1)) {
        importedContainer.importContainerData(fio, packer);
    }
    assertEquals(schemaV3Enabled ? SCHEMA_V3 : SCHEMA_V2, importedContainer.getContainerData().getSchemaVersion());
    assertEquals(pendingDeleteBlockCount, importedContainer.getContainerData().getNumPendingDeletionBlocks());
}

