public void testContainerReader(ContainerTestVersionInfo versionInfo) throws Exception {
    setLayoutAndSchemaVersion(versionInfo);
    setup(versionInfo);
    KeyValueContainerData recoveringContainerData = new KeyValueContainerData(10, layout, (long) StorageUnit.GB.toBytes(5), UUID.randomUUID().toString(), datanodeId.toString());
    //create a container with recovering state
    recoveringContainerData.setState(RECOVERING);
    KeyValueContainer recoveringKeyValueContainer = new KeyValueContainer(recoveringContainerData, conf);
    recoveringKeyValueContainer.create(volumeSet, volumeChoosingPolicy, clusterId);
    ContainerReader containerReader = new ContainerReader(volumeSet, hddsVolume, containerSet, conf, true);
    Thread thread = new Thread(containerReader);
    thread.start();
    thread.join();
    //recovering container should be marked unhealthy, so the count should be 3
    assertEquals(UNHEALTHY, containerSet.getContainer(recoveringContainerData.getContainerID()).getContainerState());
    assertEquals(3, containerSet.containerCount());
    for (int i = 0; i < 2; i++) {
        Container keyValueContainer = containerSet.getContainer(i);
        KeyValueContainerData keyValueContainerData = (KeyValueContainerData) keyValueContainer.getContainerData();
        // Verify block related metadata.
        assertEquals(blockCount, keyValueContainerData.getBlockCount());
        assertEquals(blockCount * blockLen, keyValueContainerData.getBytesUsed());
