@Test
public void testInconsistentChecksumContainerShouldThrowError() throws Exception {
    // create container
    long containerId = 1;
    KeyValueContainerData containerData = spy(new KeyValueContainerData(containerId, ContainerLayoutVersion.FILE_PER_BLOCK, 100, "test", "test"));
    // mock to return different checksum
    when(containerData.getChecksum()).thenReturn("checksum1", "checksum2");
    doNothing().when(containerData).setChecksumTo0ByteArray();
    // create containerImporter object
    ContainerController controllerMock = mock(ContainerController.class);
    ContainerSet containerSet = new ContainerSet(0);
    MutableVolumeSet volumeSet = new MutableVolumeSet("test", conf, null, StorageVolume.VolumeType.DATA_VOLUME, null);
    ContainerImporter containerImporter = spy(new ContainerImporter(conf, containerSet, controllerMock, volumeSet));
    TarContainerPacker packer = mock(TarContainerPacker.class);
    when(packer.unpackContainerDescriptor(any())).thenReturn("test".getBytes(StandardCharsets.UTF_8));
    when(containerImporter.getPacker(any())).thenReturn(packer);
    doReturn(containerData).when(containerImporter).getKeyValueContainerData(any(byte[].class));
    when(containerImporter.getImportContainerProgress()).thenReturn(new HashSet<>());
    File tarFile = File.createTempFile("temp_" + System.currentTimeMillis(), ".tar");
    StorageContainerException scException = assertThrows(StorageContainerException.class, () -> containerImporter.importContainer(containerId, tarFile.toPath(), null, NO_COMPRESSION));
    Assertions.assertTrue(scException.getMessage().contains("Container checksum error"));
}

