public void init(boolean isZeroCopy) throws Exception {
    conf = new OzoneConfiguration();
    ReplicationServer.ReplicationConfig replicationConfig = conf.getObject(ReplicationServer.ReplicationConfig.class);
    replicationConfig.setZeroCopyEnable(isZeroCopy);
    SecurityConfig secConf = new SecurityConfig(conf);
    ContainerSet containerSet = new ContainerSet(1000);
    DatanodeDetails.Builder dn = DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).setHostName("localhost").setIpAddress("127.0.0.1").setPersistedOpState(HddsProtos.NodeOperationalState.IN_SERVICE).setPersistedOpStateExpiry(0);
    DatanodeDetails.Port containerPort = DatanodeDetails.newPort(DatanodeDetails.Port.Name.STANDALONE, OzoneConfigKeys.HDDS_CONTAINER_IPC_PORT_DEFAULT);
    DatanodeDetails.Port ratisPort = DatanodeDetails.newPort(DatanodeDetails.Port.Name.RATIS, OzoneConfigKeys.HDDS_CONTAINER_RATIS_IPC_PORT_DEFAULT);
    DatanodeDetails.Port replicationPort = DatanodeDetails.newPort(DatanodeDetails.Port.Name.REPLICATION, replicationConfig.getPort());
    DatanodeDetails.Port streamPort = DatanodeDetails.newPort(DatanodeDetails.Port.Name.RATIS_DATASTREAM, OzoneConfigKeys.HDDS_CONTAINER_RATIS_DATASTREAM_PORT_DEFAULT);
    dn.addPort(containerPort);
    dn.addPort(ratisPort);
    dn.addPort(replicationPort);
    dn.addPort(streamPort);
    datanode = dn.build();
    final String testDir = Files.createDirectory(tempDir.resolve("VolumeDir")).toString();
    MutableVolumeSet volumeSet = mock(MutableVolumeSet.class);
    when(volumeSet.getVolumesList()).thenReturn(Collections.singletonList(new HddsVolume.Builder(testDir).conf(conf).build()));
    ContainerMetrics metrics = ContainerMetrics.create(conf);
    Handler containerHandler = new KeyValueHandler(conf, datanode.getUuidString(), containerSet, volumeSet, metrics, c -> {
    });
    containerController = new ContainerController(containerSet, Collections.singletonMap(ContainerProtos.ContainerType.KeyValueContainer, containerHandler));
    KeyValueContainerData data = new KeyValueContainerData(CONTAINER_ID, ContainerLayoutVersion.FILE_PER_BLOCK, GB, UUID.randomUUID().toString(), datanode.getUuidString());
    KeyValueContainer container = new KeyValueContainer(data, conf);
    StorageVolumeUtil.getHddsVolumesList(volumeSet.getVolumesList()).forEach(hddsVolume -> hddsVolume.setDbParentDir(tempDir.toFile()));
    container.create(volumeSet, new RoundRobinVolumeChoosingPolicy(), "test-replication");
    containerSet.addContainer(container);
    container.close();
    ContainerImporter importer = mock(ContainerImporter.class);
    doAnswer(invocation -> {
        pushContainerId.set((long) invocation.getArguments()[0]);
        return null;
    }).when(importer).importContainer(anyLong(), any(), any(), any());
    doReturn(true).when(importer).isAllowedContainerImport(eq(CONTAINER_ID));
    when(importer.chooseNextVolume()).thenReturn(new HddsVolume.Builder(Files.createDirectory(tempDir.resolve("ImporterDir")).toString()).conf(conf).build());
    replicationServer = new ReplicationServer(containerController, replicationConfig, secConf, null, importer, datanode.threadNamePrefix());
    replicationServer.start();
}

