@Test
void closesStreamOnError() {
    // GIVEN
    ContainerReplicationSource source = new ContainerReplicationSource() {

        @Override
        public void prepare(long containerId) {
            // no-op
        }

        @Override
        public void copyData(long containerId, OutputStream destination, CopyContainerCompression compression) throws IOException {
            throw new IOException("testing");
        }
    };
    ContainerImporter importer = mock(ContainerImporter.class);
    GrpcReplicationService subject = new GrpcReplicationService(source, importer, false);
    CopyContainerRequestProto request = CopyContainerRequestProto.newBuilder().setContainerID(1).setReadOffset(0).setLen(123).build();
    CallStreamObserver<CopyContainerResponseProto> observer = mock(CallStreamObserver.class);
    when(observer.isReady()).thenReturn(true);
    // WHEN
    subject.download(request, observer);
    // THEN
    // onCompleted is called by GrpcOutputStream#close
    // so we indirectly verify that the stream is closed
    verify(observer).onCompleted();
}

