private ContainerReplicator createSubject(long containerID, DatanodeDetails target, OutputStream outputStream, Consumer<CompletableFuture<Void>> completion, CopyContainerCompression compression) throws IOException {
    ContainerReplicationSource source = mock(ContainerReplicationSource.class);
    ContainerUploader uploader = mock(ContainerUploader.class);
    ArgumentCaptor<CompletableFuture<Void>> futureArgument = ArgumentCaptor.forClass(CompletableFuture.class);
    ArgumentCaptor<CopyContainerCompression> compressionArgument = ArgumentCaptor.forClass(CopyContainerCompression.class);
    when(uploader.startUpload(eq(containerID), eq(target), futureArgument.capture(), compressionArgument.capture())).thenReturn(outputStream);
    doAnswer(invocation -> {
        compressionArgument.getAllValues().forEach(c -> assertEquals(compression, c));
        completion.accept(futureArgument.getValue());
        return null;
    }).when(source).copyData(eq(containerID), any(), compressionArgument.capture());
    return new PushReplicator(conf, source, uploader);
}

