@ContainerLayoutTestInfo.ContainerTest
public void testDownloadAndImportReplicatorFailure(ContainerLayoutVersion layout, @TempDir File tempFile) throws IOException {
    OzoneConfiguration conf = new OzoneConfiguration();
    ReplicationSupervisor supervisor = ReplicationSupervisor.newBuilder().stateContext(context).executor(newDirectExecutorService()).clock(clock).build();
    // Mock to fetch an exception in the importContainer method.
    SimpleContainerDownloader moc = mock(SimpleContainerDownloader.class);
    Path res = Paths.get("file:/tmp/no-such-file");
    when(moc.getContainerDataFromReplicas(anyLong(), anyList(), any(Path.class), any())).thenReturn(res);
    final String testDir = tempFile.getPath();
    MutableVolumeSet volumeSet = mock(MutableVolumeSet.class);
    when(volumeSet.getVolumesList()).thenReturn(singletonList(new HddsVolume.Builder(testDir).conf(conf).build()));
    ContainerController mockedCC = mock(ContainerController.class);
    ContainerImporter importer = new ContainerImporter(conf, set, mockedCC, volumeSet);
    ContainerReplicator replicator = new DownloadAndImportReplicator(conf, set, importer, moc);
    replicatorRef.set(replicator);
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(DownloadAndImportReplicator.LOG);
    supervisor.addTask(createTask(1L));
    assertEquals(1, supervisor.getReplicationFailureCount());
    assertEquals(0, supervisor.getReplicationSuccessCount());
    assertThat(logCapturer.getOutput()).contains("Container 1 replication was unsuccessful.");
}

