@Test
public void testRenewAndStoreKeyAndCertificate() throws Exception {
    // save the certificate on dn
    CertificateCodec certCodec = new CertificateCodec(dnSecurityConfig, dnSecurityConfig.getCertificateLocation(DN_COMPONENT));
    certCodec.writeCertificate(x509Certificate);
    X509Certificate newCert = generateX509Cert(null);
    String pemCert = CertificateCodec.getPEMEncodedString(newCert);
    SCMGetCertResponseProto responseProto = SCMGetCertResponseProto.newBuilder().setResponseCode(SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).build();
    when(scmSecurityClient.getDataNodeCertificateChain(any(), anyString())).thenReturn(responseProto);
    String certID = dnCertClient.getCertificate().getSerialNumber().toString();
    // a success renew
    String newCertId = dnCertClient.renewAndStoreKeyAndCertificate(true);
    assertNotEquals(certID, newCertId);
    assertEquals(dnCertClient.getCertificate().getSerialNumber().toString(), certID);
    File newKeyDir = new File(dnSecurityConfig.getKeyLocation(dnCertClient.getComponentName()).toString() + HddsConfigKeys.HDDS_NEW_KEY_CERT_DIR_NAME_SUFFIX);
    File newCertDir = new File(dnSecurityConfig.getCertificateLocation(dnCertClient.getComponentName()).toString() + HddsConfigKeys.HDDS_NEW_KEY_CERT_DIR_NAME_SUFFIX);
    File backupKeyDir = new File(dnSecurityConfig.getKeyLocation(dnCertClient.getComponentName()).toString() + HddsConfigKeys.HDDS_BACKUP_KEY_CERT_DIR_NAME_SUFFIX);
    File backupCertDir = new File(dnSecurityConfig.getCertificateLocation(dnCertClient.getComponentName()).toString() + HddsConfigKeys.HDDS_BACKUP_KEY_CERT_DIR_NAME_SUFFIX);
    // backup directories exist
    assertTrue(backupKeyDir.exists());
    assertTrue(backupCertDir.exists());
    // new directories should not exist
    assertFalse(newKeyDir.exists());
    assertFalse(newCertDir.exists());
    // cleanup backup key and cert dir
    dnCertClient.cleanBackupDir();
    Files.createDirectories(newKeyDir.toPath());
    Files.createDirectories(newCertDir.toPath());
    KeyPair keyPair = KeyStoreTestUtil.generateKeyPair("RSA");
    KeyCodec newKeyCodec = new KeyCodec(dnSecurityConfig, newKeyDir.toPath());
    newKeyCodec.writeKey(keyPair);
    X509Certificate cert = KeyStoreTestUtil.generateCertificate("CN=OzoneMaster", keyPair, 30, "SHA256withRSA");
    certCodec = new CertificateCodec(dnSecurityConfig, newCertDir.toPath());
    dnCertClient.storeCertificate(getPEMEncodedString(cert), CAType.NONE, certCodec, false, false);
    // a success renew after auto cleanup new key and cert dir
    dnCertClient.renewAndStoreKeyAndCertificate(true);
}

