    processingResult.join();
    //The root ca processors are invoked
    assertTrue(isProcessed.get());
}

@Test
public void testPollerRetriesAfterFailure() throws Exception {
    //Given a the root ca poller knowing about a root ca certificate and the
    // SCM providing a new one
    X509Certificate knownCert = generateX509Cert(LocalDateTime.now(), Duration.ofSeconds(50));
    X509Certificate newRootCa = generateX509Cert(LocalDateTime.now(), Duration.ofSeconds(50));
    HashSet<X509Certificate> knownCerts = new HashSet<>();
    knownCerts.add(knownCert);
    List<String> certsFromScm = new ArrayList<>();
    certsFromScm.add(CertificateCodec.getPEMEncodedString(knownCert));
    certsFromScm.add(CertificateCodec.getPEMEncodedString(newRootCa));
    RootCaRotationPoller poller = new RootCaRotationPoller(secConf, knownCerts, scmSecurityClient, "");
    when(scmSecurityClient.getAllRootCaCertificates()).thenReturn(certsFromScm);
    CompletableFuture<Void> processingResult = new CompletableFuture<>();
    //When encountering an error for the first run:
    AtomicInteger runNumber = new AtomicInteger(1);
    poller.addRootCARotationProcessor(certificates -> {
        if (runNumber.getAndIncrement() < 2) {
            poller.setCertificateRenewalError();
        }
        assertEquals(certificates.size(), 2);
        processingResult.complete(null);
        return processingResult;
    });
    //Then the first run encounters an error
    poller.pollRootCas();
    processingResult.join();
    assertThat(logCapturer.getOutput()).contains("There was a caught exception when trying to sign the certificate");
    //And then the second clean run is successful.
    poller.pollRootCas();
    assertThat(logCapturer.getOutput()).contains("Certificate processing was successful.");
}

@Test
public void testRequestQuoting() throws Exception {
    HttpServletRequest mockReq = mock(HttpServletRequest.class);
    HttpServer2.QuotingInputFilter.RequestQuoter quoter = new HttpServer2.QuotingInputFilter.RequestQuoter(mockReq);
    doReturn("a<b").when(mockReq).getParameter("x");
    assertEquals("a&lt;b", quoter.getParameter("x"), "Test simple param quoting");
    doReturn(null).when(mockReq).getParameter("x");
    assertNull(quoter.getParameter("x"), "Test that missing parameters dont cause NPE");
    doReturn(new String[] { "a<b", "b" }).when(mockReq).getParameterValues("x");
    assertArrayEquals(new String[] { "a&lt;b", "b" }, quoter.getParameterValues("x"), "Test escaping of an array");
    doReturn(null).when(mockReq).getParameterValues("x");
    assertNull(quoter.getParameterValues("x"), "Test that missing parameters dont cause NPE for array");
}

