public void testForeachRemainingCallsConsumerWithAllElements() {
    when(rocksDBIteratorMock.isValid()).thenReturn(true, true, true, true, true, true, true, false);
    when(rocksDBIteratorMock.key()).thenReturn(new byte[] { 0x00 }, new byte[] { 0x00 }, new byte[] { 0x01 }, new byte[] { 0x02 }).thenThrow(new NoSuchElementException());
    when(rocksDBIteratorMock.value()).thenReturn(new byte[] { 0x7f }, new byte[] { 0x7f }, new byte[] { 0x7e }, new byte[] { 0x7d }).thenThrow(new NoSuchElementException());
    final Consumer<Table.KeyValue<byte[], byte[]>> consumerStub = mock(Consumer.class);
    RDBStoreByteArrayIterator iter = newIterator();
    iter.forEachRemaining(consumerStub);
    ArgumentCaptor<RawKeyValue.ByteArray> capture = forClass(RawKeyValue.ByteArray.class);
    verify(consumerStub, times(3)).accept(capture.capture());
    assertArrayEquals(new byte[] { 0x00 }, capture.getAllValues().get(0).getKey());
    assertArrayEquals(new byte[] { 0x7f }, capture.getAllValues().get(0).getValue());
    assertArrayEquals(new byte[] { 0x01 }, capture.getAllValues().get(1).getKey());
    assertArrayEquals(new byte[] { 0x7e }, capture.getAllValues().get(1).getValue());
    assertArrayEquals(new byte[] { 0x02 }, capture.getAllValues().get(2).getKey());
    assertArrayEquals(new byte[] { 0x7d }, capture.getAllValues().get(2).getValue());
}

