public void testCall() throws Exception {
    callDeletedBlockTransactionScanner();
    ArgumentCaptor<CommandForDatanode> argumentCaptor = ArgumentCaptor.forClass(CommandForDatanode.class);
    // Three Datanode is healthy and in-service, and the task queue is empty,
    // so the transaction will send to all three Datanode
    verify(eventPublisher, times(3)).fireEvent(eq(SCMEvents.DATANODE_COMMAND), argumentCaptor.capture());
    List<CommandForDatanode> actualCommands = argumentCaptor.getAllValues();
    List<UUID> actualDnIds = actualCommands.stream().map(CommandForDatanode::getDatanodeId).collect(Collectors.toList());
    Set<UUID> expectedDnIdsSet = datanodeDetails.stream().map(DatanodeDetails::getUuid).collect(Collectors.toSet());
    assertEquals(expectedDnIdsSet, new HashSet<>(actualDnIds));
    assertEquals(datanodeDetails.size(), metrics.getNumBlockDeletionCommandSent());
