@Test
public void testLimitCommandSending() throws Exception {
    DatanodeConfiguration dnConf = conf.getObject(DatanodeConfiguration.class);
    int pendingCommandLimit = dnConf.getBlockDeleteQueueLimit();
    // The number of commands pending on all Datanodes has reached the limit.
    when(nodeManager.getTotalDatanodeCommandCount(any(), any())).thenReturn(pendingCommandLimit);
    assertEquals(0, service.getDatanodesWithinCommandLimit(datanodeDetails).size());
    // The number of commands pending on all Datanodes is 0
    when(nodeManager.getTotalDatanodeCommandCount(any(), any())).thenReturn(0);
    assertEquals(datanodeDetails.size(), service.getDatanodesWithinCommandLimit(datanodeDetails).size());
    // The number of commands pending on first Datanodes has reached the limit.
    DatanodeDetails fullDatanode = datanodeDetails.get(0);
    when(nodeManager.getTotalDatanodeCommandCount(fullDatanode, Type.deleteBlocksCommand)).thenReturn(pendingCommandLimit);
    Set<DatanodeDetails> includeNodes = service.getDatanodesWithinCommandLimit(datanodeDetails);
    assertEquals(datanodeDetails.size() - 1, includeNodes.size());
    assertFalse(includeNodes.contains(fullDatanode));
}

