public void checkIterationResultTimeout() throws NodeNotFoundException, IOException, IllegalContainerBalancerStateException, InvalidContainerBalancerConfigurationException, TimeoutException {
    CompletableFuture<MoveManager.MoveResult> completedFuture = CompletableFuture.completedFuture(MoveManager.MoveResult.COMPLETED);
    when(replicationManager.move(any(ContainerID.class), any(DatanodeDetails.class), any(DatanodeDetails.class))).thenReturn(completedFuture).thenAnswer(invocation -> genCompletableFuture(2000));
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxSizeEnteringTarget(10 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeToMovePerIteration(100 * STORAGE_UNIT);
