    /*
    Disable LegacyReplicationManager. This means balancer should select RATIS
     as well as EC containers for balancing. Also, MoveManager will be used.
     */
    when(replicationManager.getConfig()).thenReturn(rmConf);
    rmConf.setEnableLegacy(false);
    // these configs will usually be specified in each test
    balancerConfiguration = conf.getObject(ContainerBalancerConfiguration.class);
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMaxSizeToMovePerIteration(50 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeEnteringTarget(50 * STORAGE_UNIT);
    conf.setFromObject(balancerConfiguration);
    GenericTestUtils.setLogLevel(ContainerBalancerTask.LOG, Level.DEBUG);
    int[] sizeArray = testInfo.getTestMethod().filter(method -> method.getName().equals("balancerShouldMoveOnlyPositiveSizeContainers")).map(method -> new int[] { 0, 0, 0, 0, 0, 1, 2, 3, 4, 5 }).orElse(null);
    createCluster(sizeArray);
    mockNodeManager = new MockNodeManager(datanodeToContainersMap);
    NetworkTopology clusterMap = mockNodeManager.getClusterNetworkTopologyMap();
    placementPolicy = ContainerPlacementPolicyFactory.getPolicy(conf, mockNodeManager, clusterMap, true, SCMContainerPlacementMetrics.create());
    ecPlacementPolicy = ContainerPlacementPolicyFactory.getECPolicy(conf, mockNodeManager, clusterMap, true, SCMContainerPlacementMetrics.create());
    placementPolicyValidateProxy = new PlacementPolicyValidateProxy(placementPolicy, ecPlacementPolicy);
    when(replicationManager.isContainerReplicatingOrDeleting(any(ContainerID.class))).thenReturn(false);
    when(replicationManager.move(any(ContainerID.class), any(DatanodeDetails.class), any(DatanodeDetails.class))).thenReturn(CompletableFuture.completedFuture(MoveManager.MoveResult.COMPLETED));
    when(replicationManager.getClock()).thenReturn(Clock.system(ZoneId.systemDefault()));
    when(containerManager.getContainerReplicas(any(ContainerID.class))).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return cidToReplicasMap.get(cid);
    });
    when(containerManager.getContainer(any(ContainerID.class))).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return cidToInfoMap.get(cid);
    });
    when(containerManager.getContainers()).thenReturn(new ArrayList<>(cidToInfoMap.values()));
    when(scm.getScmNodeManager()).thenReturn(mockNodeManager);
    when(scm.getContainerPlacementPolicy()).thenReturn(placementPolicy);
    when(scm.getContainerManager()).thenReturn(containerManager);
    when(scm.getReplicationManager()).thenReturn(replicationManager);
    when(scm.getScmContext()).thenReturn(SCMContext.emptyContext());
    when(scm.getClusterMap()).thenReturn(null);
    when(scm.getEventQueue()).thenReturn(mock(EventPublisher.class));
    when(scm.getConfiguration()).thenReturn(conf);
    when(scm.getStatefulServiceStateManager()).thenReturn(serviceStateManager);
    when(scm.getSCMServiceManager()).thenReturn(scmServiceManager);
    when(scm.getPlacementPolicyValidateProxy()).thenReturn(placementPolicyValidateProxy);
    when(scm.getMoveManager()).thenReturn(moveManager);
    /*
    When StatefulServiceStateManager#saveConfiguration is called, save to
    in-memory serviceToConfigMap instead.
     */
    doAnswer(i -> {
        serviceToConfigMap.put(i.getArgument(0, String.class), i.getArgument(1, ByteString.class));
        return null;
    }).when(serviceStateManager).saveConfiguration(any(String.class), any(ByteString.class));
    /*
    When StatefulServiceStateManager#readConfiguration is called, read from
    serviceToConfigMap instead.
     */
    when(serviceStateManager.readConfiguration(anyString())).thenAnswer(i -> serviceToConfigMap.get(i.getArgument(0, String.class)));
    doNothing().when(scmServiceManager).register(any(SCMService.class));
    ContainerBalancer sb = new ContainerBalancer(scm);
    containerBalancerTask = new ContainerBalancerTask(scm, 0, sb, sb.getMetrics(), balancerConfiguration, false);
}

