@Test
public void testCloseCommandSentForMismatchedReplicas() {
    ContainerInfo containerInfo = ReplicationTestUtil.createContainerInfo(ecReplicationConfig, 1, CLOSED);
    Set<ContainerReplica> containerReplicas = ReplicationTestUtil.createReplicas(containerInfo.containerID(), ContainerReplicaProto.State.CLOSED, 1, 2);
    ContainerReplica mismatch1 = ReplicationTestUtil.createContainerReplica(containerInfo.containerID(), 4, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.OPEN);
    ContainerReplica mismatch2 = ReplicationTestUtil.createContainerReplica(containerInfo.containerID(), 5, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.CLOSING);
    ContainerReplica mismatch3 = ReplicationTestUtil.createContainerReplica(containerInfo.containerID(), 3, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    containerReplicas.add(mismatch1);
    containerReplicas.add(mismatch2);
    containerReplicas.add(mismatch3);
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).build();
    ContainerCheckRequest readRequest = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).setReadOnly(true).build();
    // this handler always returns false so other handlers can fix issues
    // such as under replication
    assertFalse(handler.handle(request));
    assertFalse(handler.handle(readRequest));
    verify(replicationManager, times(1)).sendCloseContainerReplicaCommand(containerInfo, mismatch1.getDatanodeDetails(), true);
    verify(replicationManager, times(1)).sendCloseContainerReplicaCommand(containerInfo, mismatch2.getDatanodeDetails(), true);
    // close command should not be sent for unhealthy replica
    verify(replicationManager, times(0)).sendCloseContainerReplicaCommand(containerInfo, mismatch3.getDatanodeDetails(), true);
}

