private void testOverReplicationWithIndexes(Set<ContainerReplica> availableReplicas, Map<Integer, Integer> index2excessNum, List<ContainerReplicaOp> pendingOps) throws NotLeaderException, CommandTargetOverloadedException {
    ECOverReplicationHandler ecORH = new ECOverReplicationHandler(policy, replicationManager);
    ContainerHealthResult.OverReplicatedHealthResult result = mock(ContainerHealthResult.OverReplicatedHealthResult.class);
    when(result.getContainerInfo()).thenReturn(container);
    ecORH.processAndSendCommands(availableReplicas, pendingOps, result, 1);
    // total commands send out should be equal to the sum of all
    // the excess nums
    int totalDeleteCommandNum = index2excessNum.values().stream().reduce(0, Integer::sum);
    assertEquals(totalDeleteCommandNum, commandsSent.size());
    // Each command should have a non-zero replica index
    commandsSent.forEach(pair -> assertNotEquals(0, ((DeleteContainerCommand) pair.getValue()).getReplicaIndex()));
    // command num of each index should be equal to the excess num
    // of this index
    Map<DatanodeDetails, Integer> datanodeDetails2Index = availableReplicas.stream().collect(Collectors.toMap(ContainerReplica::getDatanodeDetails, ContainerReplica::getReplicaIndex));
    Map<Integer, Integer> index2commandNum = new HashMap<>();
    commandsSent.forEach(pair -> index2commandNum.merge(datanodeDetails2Index.get(pair.getKey()), 1, Integer::sum));
    index2commandNum.keySet().forEach(i -> {
        assertThat(index2excessNum).containsKey(i);
        assertEquals(index2commandNum.get(i), index2excessNum.get(i));
    });
}

