@Test
public void testDeleteThrottling() throws IOException {
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(IN_SERVICE, 5));
    ContainerHealthResult.UnderReplicatedHealthResult health = new ContainerHealthResult.UnderReplicatedHealthResult(container, 2, false, false, false);
    // On the first call to throttled delete, throw an overloaded exception.
    final AtomicBoolean shouldThrow = new AtomicBoolean(true);
    // On the first call we throw, on subsequent calls we succeed.
    doAnswer((Answer<Void>) invocationOnMock -> {
        if (shouldThrow.get()) {
            shouldThrow.set(false);
            throw new CommandTargetOverloadedException("Test exception");
        }
        ContainerInfo containerInfo = invocationOnMock.getArgument(0);
        int replicaIndex = invocationOnMock.getArgument(1);
        DatanodeDetails target = invocationOnMock.getArgument(2);
        boolean forceDelete = invocationOnMock.getArgument(3);
        DeleteContainerCommand deleteCommand = new DeleteContainerCommand(containerInfo.getContainerID(), forceDelete);
        deleteCommand.setReplicaIndex(replicaIndex);
        commandsSent.add(Pair.of(target, deleteCommand));
        return null;
    }).when(replicationManager).sendThrottledDeleteCommand(any(), anyInt(), any(), anyBoolean());
    ECOverReplicationHandler ecORH = new ECOverReplicationHandler(policy, replicationManager);
    assertThrows(CommandTargetOverloadedException.class, () -> ecORH.processAndSendCommands(availableReplicas, ImmutableList.of(), health, 1));
    assertEquals(1, commandsSent.size());
}

