    // quasi2 should be closed since its BCSID matches the container's.
    // delete command should be sent for quasiToDelete to unblock under rep
    // handling.
    assertDeleteScheduled(1);
    assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.closeContainerCommand, quasi2.getDatanodeDetails()));
    assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.deleteContainerCommand, quasiToDelete.getDatanodeDetails()));
    assertUnderReplicatedCount(1);
