@Test
public void overReplicatedButRemovingMakesMisReplicated() throws IOException, TimeoutException {
    // In this test, the excess replica should not be removed.
    final ContainerInfo container = getContainer(LifeCycleState.CLOSED);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaFour = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    containerStateManager.updateContainerReplica(id, replicaFour);
    // Ensure a mis-replicated status is returned for any containers in this
    // test where there are exactly 3 replicas checked.
    when(ratisContainerPlacementPolicy.validateContainerPlacement(argThat(list -> list.size() == 3), anyInt())).thenAnswer(invocation -> new ContainerPlacementStatusDefault(1, 2, 3));
    int currentDeleteCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // TODO the new (non-legacy) RM needs a separate handler for
    //  topology status to make progress in this case by:
    //  1. Deleting the closed replica to restore proper replica count.
    //  2. Deleting the unhealthy replica since there are adequate healthy
    //  replicas.
    //  3. Fixing topology issues left by the previous cleanup tasks.
    // Current legacy RM implementation will take no action in this case
    // because deletion would compromise topology.
    assertEquals(currentDeleteCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    assertEquals(currentDeleteCommandCount, replicationManager.getMetrics().getDeletionCmdsSentTotal());
    assertEquals(0, getInflightCount(InflightType.DELETION));
    assertEquals(0, replicationManager.getMetrics().getInflightDeletion());
    assertOverReplicatedCount(1);
}

