protected void testMisReplication(Set<ContainerReplica> availableReplicas, PlacementPolicy mockedPlacementPolicy, List<ContainerReplicaOp> pendingOp, int maintenanceCnt, int misreplicationCount, int expectedNumberOfNodes, int expectedNumberOfCommands) throws IOException {
    MisReplicationHandler misReplicationHandler = getMisreplicationHandler(mockedPlacementPolicy, conf, replicationManager);
    ContainerHealthResult.MisReplicatedHealthResult result = mock(ContainerHealthResult.MisReplicatedHealthResult.class);
    when(result.isReplicatedOkAfterPending()).thenReturn(false);
    when(result.getContainerInfo()).thenReturn(container);
    Map<ContainerReplica, Boolean> sources = availableReplicas.stream().collect(Collectors.toMap(Function.identity(), r -> {
        if (r.getDatanodeDetails().getPersistedOpState() == IN_SERVICE) {
            try {
                return replicationManager.getNodeStatus(r.getDatanodeDetails()).isHealthy();
            } catch (NodeNotFoundException e) {
                throw new RuntimeException(e);
            }
        }
        return false;
    }));
    Set<DatanodeDetails> sourceDns = sources.entrySet().stream().filter(Map.Entry::getValue).map(Map.Entry::getKey).map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet());
    Set<ContainerReplica> copy = sources.entrySet().stream().filter(Map.Entry::getValue).limit(misreplicationCount).map(Map.Entry::getKey).collect(Collectors.toSet());
    when(mockedPlacementPolicy.replicasToCopyToFixMisreplication(anyMap())).thenAnswer(invocation -> copy);
    Set<DatanodeDetails> remainingReplicasAfterCopy = availableReplicas.stream().filter(r -> !copy.contains(r)).map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet());
    List<DatanodeDetails> targetNodes = IntStream.range(0, expectedNumberOfNodes).mapToObj(i -> MockDatanodeDetails.randomDatanodeDetails()).collect(Collectors.toList());
    if (expectedNumberOfNodes > 0) {
        when(mockedPlacementPolicy.chooseDatanodes(any(), any(), any(), eq(copy.size()), anyLong(), anyLong())).thenAnswer(invocation -> {
            List<DatanodeDetails> datanodeDetails = invocation.getArgument(0);
            assertThat(remainingReplicasAfterCopy).containsAll(datanodeDetails);
            return targetNodes;
        });
    }
    Map<DatanodeDetails, Integer> replicaIndexMap = copy.stream().collect(Collectors.toMap(ContainerReplica::getDatanodeDetails, ContainerReplica::getReplicaIndex));
    try {
        misReplicationHandler.processAndSendCommands(availableReplicas, pendingOp, result, maintenanceCnt);
    } finally {
        assertEquals(expectedNumberOfCommands, commandsSent.size());
        for (Pair<DatanodeDetails, SCMCommand<?>> pair : commandsSent) {
            SCMCommand<?> command = pair.getValue();
            assertSame(replicateContainerCommand, command.getType());
            ReplicateContainerCommand replicateContainerCommand = (ReplicateContainerCommand) command;
            assertEquals(replicateContainerCommand.getContainerID(), container.getContainerID());
            DatanodeDetails replicateSrcDn = pair.getKey();
            DatanodeDetails target = replicateContainerCommand.getTargetDatanode();
            assertThat(sourceDns).contains(replicateSrcDn);
            assertThat(targetNodes).contains(target);
            int replicaIndex = replicateContainerCommand.getReplicaIndex();
            assertReplicaIndex(replicaIndexMap, replicateSrcDn, replicaIndex);
        }
    }
}

