/**
 * Closed container with 4 closed replicas and 1 quasi closed replica. This
 * container is over replicated and the handler should create a delete
 * command for the quasi closed replica even if it violates the placement
 * policy. Once the quasi closed container is removed and we have 4
 * replicas, then the mocked placement policy considers the container mis
 * replicated. As long as the rack count does not change, another replica
 * can be removed.
 */
@Test
public void testOverReplicatedClosedContainerWithQuasiClosedReplica() throws IOException {
    Set<ContainerReplica> replicas = createReplicas(container.containerID(), ContainerReplicaProto.State.CLOSED, 0, 0, 0, 0);
    ContainerReplica quasiClosedReplica = createContainerReplica(container.containerID(), 0, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.QUASI_CLOSED);
    replicas.add(quasiClosedReplica);
    // Ensure a mis-replicated status is returned when 4 or fewer replicas are
    // checked.
    when(policy.validateContainerPlacement(argThat(list -> list.size() <= 4), anyInt())).thenReturn(new ContainerPlacementStatusDefault(1, 2, 3));
    Set<Pair<DatanodeDetails, SCMCommand<?>>> commands = testProcessing(replicas, Collections.emptyList(), getOverReplicatedHealthResult(), 2);
    Set<DatanodeDetails> datanodes = commands.stream().map(Pair::getKey).collect(Collectors.toSet());
    assertThat(datanodes).contains(quasiClosedReplica.getDatanodeDetails());
}

