/**
 * The container is quasi closed. All replicas are quasi closed but
 * originate from different datanodes. While this container is over
 * replicated, handler should not create a delete command for any replica. It
 * tries to preserve one replica per unique origin datanode.
 */
@Test
public void testOverReplicatedQuasiClosedContainerWithDifferentOrigins() throws IOException, NodeNotFoundException {
    container = createContainer(HddsProtos.LifeCycleState.QUASI_CLOSED, RATIS_REPLICATION_CONFIG);
    Set<ContainerReplica> replicas = createReplicas(container.containerID(), ContainerReplicaProto.State.QUASI_CLOSED, 0, 0, 0, 0, 0);
    /*
     Even an unhealthy replica shouldn't be deleted if it has a unique
     origin. It might be possible to close this replica in the future.
     */
    ContainerReplica unhealthyReplica = createContainerReplica(container.containerID(), 0, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    replicas.add(unhealthyReplica);
    testProcessing(replicas, Collections.emptyList(), getOverReplicatedHealthResult(), 0);
    /*
    Now, introduce two UNHEALTHY replicas that share the same origin node as
    the existing UNHEALTHY replica. They're on decommissioning and stale
    nodes, respectively. Still no replica should be deleted, because these are
    likely going away soon anyway.
     */
    replicas.add(createContainerReplica(container.containerID(), 0, DECOMMISSIONING, State.UNHEALTHY, container.getNumberOfKeys(), container.getUsedBytes(), MockDatanodeDetails.randomDatanodeDetails(), unhealthyReplica.getOriginDatanodeId()));
    DatanodeDetails staleNode = MockDatanodeDetails.randomDatanodeDetails();
    replicas.add(createContainerReplica(container.containerID(), 0, IN_SERVICE, State.UNHEALTHY, container.getNumberOfKeys(), container.getUsedBytes(), staleNode, unhealthyReplica.getOriginDatanodeId()));
    when(replicationManager.getNodeStatus(eq(staleNode))).thenAnswer(invocation -> {
        DatanodeDetails dd = invocation.getArgument(0);
        return new NodeStatus(dd.getPersistedOpState(), HddsProtos.NodeState.STALE, 0);
    });
    testProcessing(replicas, Collections.emptyList(), getOverReplicatedHealthResult(), 0);
}

