public void testOnlyHighestBcsidShouldBeASource() throws IOException {
    Set<ContainerReplica> replicas = new HashSet<>();
    replicas.add(createContainerReplica(container.containerID(), 0, IN_SERVICE, State.CLOSED, 1));
    ContainerReplica valid = createContainerReplica(container.containerID(), 0, IN_SERVICE, State.CLOSED, 2);
