/**
 * Situation: QUASI_CLOSED container with 3 QUASI_CLOSED and 1 UNHEALTHY
 * replica. They all have the same origin node id. It's expected that the
 * UNHEALTHY replica (and not a QUASI_CLOSED one) is deleted.
 */
@Test
public void testQuasiClosedContainerWithExcessUnhealthyReplica() throws IOException, NodeNotFoundException {
    when(nodeManager.getNodeStatus(any(DatanodeDetails.class))).thenReturn(NodeStatus.inServiceHealthy());
    RatisReplicationConfig ratisRepConfig = RatisReplicationConfig.getInstance(THREE);
    ContainerInfo container = createContainerInfo(ratisRepConfig, 1, HddsProtos.LifeCycleState.QUASI_CLOSED);
    Set<ContainerReplica> replicas = createReplicasWithSameOrigin(container.containerID(), ContainerReplicaProto.State.QUASI_CLOSED, 0, 0, 0);
    UUID origin = replicas.iterator().next().getOriginDatanodeId();
    ContainerReplica unhealthy = createContainerReplica(container.containerID(), 0, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY, 1, 123, MockDatanodeDetails.randomDatanodeDetails(), origin);
    replicas.add(unhealthy);
    storeContainerAndReplicas(container, replicas);
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    assertEquals(0, repQueue.underReplicatedQueueSize());
    assertEquals(1, repQueue.overReplicatedQueueSize());
    RatisOverReplicationHandler handler = new RatisOverReplicationHandler(ratisPlacementPolicy, replicationManager);
    handler.processAndSendCommands(replicas, Collections.emptyList(), repQueue.dequeueOverReplicatedContainer(), 2);
    assertTrue(commandsSent.iterator().hasNext());
    assertEquals(unhealthy.getDatanodeDetails().getUuid(), commandsSent.iterator().next().getKey());
    assertEquals(SCMCommandProto.Type.deleteContainerCommand, commandsSent.iterator().next().getValue().getType());
}

