/**
 * There is a QUASI_CLOSED container with some UNHEALTHY replicas on unique origin nodes. If the datanode hosting
 * one such replica is being taken offline, then the UNHEALTHY replica needs to be replicated to another node.
 */
@Test
public void testQuasiClosedContainerWithUnhealthyReplicaOnDecommissioningNodeWithUniqueOrigin() throws IOException, NodeNotFoundException {
    RatisReplicationConfig ratisRepConfig = RatisReplicationConfig.getInstance(THREE);
    // create a QUASI_CLOSED container with 3 QUASI_CLOSED replicas on same origin, and 1 UNHEALTHY on unique origin
    ContainerInfo container = createContainerInfo(ratisRepConfig, 1, HddsProtos.LifeCycleState.QUASI_CLOSED);
    Set<ContainerReplica> replicas = createReplicasWithSameOrigin(container.containerID(), ContainerReplicaProto.State.QUASI_CLOSED, 0, 0, 0);
    ContainerReplica unhealthy = createContainerReplica(container.containerID(), 0, DECOMMISSIONING, ContainerReplicaProto.State.UNHEALTHY);
    replicas.add(unhealthy);
    storeContainerAndReplicas(container, replicas);
    when(replicationManager.getNodeStatus(any(DatanodeDetails.class))).thenAnswer(invocation -> {
        DatanodeDetails dn = invocation.getArgument(0);
        if (dn.equals(unhealthy.getDatanodeDetails())) {
            return new NodeStatus(DECOMMISSIONING, HddsProtos.NodeState.HEALTHY);
        }
        return NodeStatus.inServiceHealthy();
    });
    // the container should be under replicated and queued to under replication queue
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    assertEquals(1, repQueue.underReplicatedQueueSize());
    assertEquals(0, repQueue.overReplicatedQueueSize());
    // next, this test sets up some mocks to test if RatisUnderReplicationHandler will handle this container correctly
    when(ratisPlacementPolicy.chooseDatanodes(anyList(), anyList(), eq(null), eq(1), anyLong(), anyLong())).thenAnswer(invocation -> ImmutableList.of(MockDatanodeDetails.randomDatanodeDetails()));
    when(nodeManager.getTotalDatanodeCommandCounts(any(DatanodeDetails.class), any(), any())).thenAnswer(invocation -> {
        Map<SCMCommandProto.Type, Integer> map = new HashMap<>();
        map.put(SCMCommandProto.Type.replicateContainerCommand, 0);
        map.put(SCMCommandProto.Type.reconstructECContainersCommand, 0);
        return map;
    });
    RatisUnderReplicationHandler handler = new RatisUnderReplicationHandler(ratisPlacementPolicy, configuration, replicationManager);
    handler.processAndSendCommands(replicas, Collections.emptyList(), repQueue.dequeueUnderReplicatedContainer(), 2);
    assertEquals(1, commandsSent.size());
    Pair<UUID, SCMCommand<?>> command = commandsSent.iterator().next();
    // a replicate command should have been sent for the UNHEALTHY replica
    assertEquals(SCMCommandProto.Type.replicateContainerCommand, command.getValue().getType());
    assertEquals(unhealthy.getDatanodeDetails().getUuid(), command.getKey());
}

/**
 * Situation: CLOSED EC container with 3 CLOSED replicas and 2 UNHEALTHY
 * replicas. This is under replication. Mocked such that the placement
 * policy throws an exception saying no target datanodes found.
 * <p>
 * Tests that EC under replication handling tries to delete an UNHEALTHY
 * replica if no target datanodes are found. It should delete only one
 * UNHEALTHY replica so that the replica's host DN becomes available as a
 * target for reconstruction/replication of a healthy replica.
 */
@Test
public void testUnderReplicationBlockedByUnhealthyReplicas() throws IOException, NodeNotFoundException {
    ContainerInfo container = createContainerInfo(repConfig, 1, HddsProtos.LifeCycleState.CLOSED);
    Set<ContainerReplica> replicas = addReplicas(container, ContainerReplicaProto.State.CLOSED, 1, 2, 3);
    ContainerReplica unhealthyReplica1 = createContainerReplica(container.containerID(), 1, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    ContainerReplica unhealthyReplica4 = createContainerReplica(container.containerID(), 4, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    replicas.add(unhealthyReplica4);
    replicas.add(unhealthyReplica1);
    // assert that this container is seen as under replicated
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(1, repQueue.underReplicatedQueueSize());
    assertEquals(0, repQueue.overReplicatedQueueSize());
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    // now, pass this container to ec under replication handling
    when(nodeManager.getNodeStatus(any(DatanodeDetails.class))).thenReturn(NodeStatus.inServiceHealthy());
    ECUnderReplicationHandler handler = new ECUnderReplicationHandler(getNoNodesTestPlacementPolicy(nodeManager, configuration), configuration, replicationManager);
    // an exception should be thrown so that this container is queued again
    assertThrows(SCMException.class, () -> handler.processAndSendCommands(replicas, containerReplicaPendingOps.getPendingOps(container.containerID()), repQueue.dequeueUnderReplicatedContainer(), 1));
    // a delete command should also have been sent for UNHEALTHY replica of
    // index 1
    assertEquals(1, commandsSent.size());
    Pair<UUID, SCMCommand<?>> command = commandsSent.iterator().next();
    assertEquals(SCMCommandProto.Type.deleteContainerCommand, command.getValue().getType());
    DeleteContainerCommand deleteCommand = (DeleteContainerCommand) command.getValue();
    assertEquals(unhealthyReplica1.getDatanodeDetails().getUuid(), command.getKey());
    assertEquals(container.containerID(), ContainerID.valueOf(deleteCommand.getContainerID()));
    assertEquals(unhealthyReplica1.getReplicaIndex(), deleteCommand.getReplicaIndex());
}

/**
 * Consider an EC container with 5 closed and 1 unhealthy replica.
 * Assume this container is also mis replicated because it's on
 * insufficient racks. For such EC containers, RM should first delete the
 * unhealthy replica and then solve mis replication.
 */
@Test
public void testMisReplicatedECContainerWithUnhealthyReplica() throws ContainerNotFoundException {
    when(ecPlacementPolicy.validateContainerPlacement(anyList(), anyInt())).thenReturn(new ContainerPlacementStatusDefault(5, 5, 5, 1, Lists.newArrayList(2, 1, 1, 1, 1)));
    ContainerInfo container = createContainerInfo(repConfig, 1, HddsProtos.LifeCycleState.CLOSED);
    Set<ContainerReplica> replicas = addReplicas(container, ContainerReplicaProto.State.CLOSED, 1, 2, 3, 4, 5);
    ContainerReplica unhealthyReplica = createContainerReplica(container.containerID(), 1, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    replicas.add(unhealthyReplica);
    storeContainerAndReplicas(container, replicas);
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(0, repQueue.underReplicatedQueueSize());
    /*
     Does not get queued as over replicated because a delete command is sent
     directly for the unhealthy replica.
     */
    assertEquals(0, repQueue.overReplicatedQueueSize());
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    List<ContainerReplicaOp> ops = containerReplicaPendingOps.getPendingOps(container.containerID());
    verify(nodeManager).addDatanodeCommand(any(), any());
    assertEquals(1, ops.size());
    assertEquals(ContainerReplicaOp.PendingOpType.DELETE, ops.get(0).getOpType());
    assertEquals(unhealthyReplica.getDatanodeDetails(), ops.get(0).getTarget());
    assertEquals(1, ops.get(0).getReplicaIndex());
    assertEquals(1, replicationManager.getMetrics().getEcDeletionCmdsSentTotal());
    assertEquals(0, replicationManager.getMetrics().getDeletionCmdsSentTotal());
    /*
    Now, remove the unhealthy replica. This leaves 5 replicas on 4 racks,
    which is mis replication. RM should queue this container as mis
    replicated now.
     */
    replicas.remove(unhealthyReplica);
    containerReplicaPendingOps.completeDeleteReplica(container.containerID(), unhealthyReplica.getDatanodeDetails(), 1);
    when(ecPlacementPolicy.validateContainerPlacement(anyList(), anyInt())).thenReturn(new ContainerPlacementStatusDefault(4, 5, 5, 1, Lists.newArrayList(2, 1, 1, 1)));
    repReport = new ReplicationManagerReport();
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(1, repQueue.underReplicatedQueueSize());
    assertEquals(0, repQueue.overReplicatedQueueSize());
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
}

