@BeforeEach
public void setup() {
    ReplicationManagerReport report = new ReplicationManagerReport();
    // Each lifecycle state has a value from 1 to N. Set the value of the metric
    // to the value by incrementing the counter that number of times.
    for (HddsProtos.LifeCycleState s : HddsProtos.LifeCycleState.values()) {
        for (int i = 0; i < s.getNumber(); i++) {
            report.increment(s);
        }
    }
    // The ordinal starts from 0, so each state will have a value of its ordinal
    for (ReplicationManagerReport.HealthState s : ReplicationManagerReport.HealthState.values()) {
        for (int i = 0; i < s.ordinal(); i++) {
            report.increment(s);
        }
    }
    final LegacyReplicationManager lrm = mock(LegacyReplicationManager.class);
    when(lrm.getInflightCount(any(InflightType.class))).thenReturn(0);
    ConfigurationSource conf = new OzoneConfiguration();
    ReplicationManager.ReplicationManagerConfiguration rmConf = conf.getObject(ReplicationManager.ReplicationManagerConfiguration.class);
    ReplicationManager replicationManager = mock(ReplicationManager.class);
    when(replicationManager.getConfig()).thenReturn(rmConf);
    when(replicationManager.getLegacyReplicationManager()).thenReturn(lrm);
    when(replicationManager.getContainerReport()).thenReturn(report);
    when(replicationManager.getContainerReplicaPendingOps()).thenReturn(mock(ContainerReplicaPendingOps.class));
    when(replicationManager.getQueue()).thenReturn(new ReplicationQueue());
    metrics = ReplicationManagerMetrics.create(replicationManager);
