    assertEquals(port, conf.getInt(ConfUtils.addKeySuffixes(OZONE_SCM_DATANODE_PORT_KEY, scmServiceId, "scm1"), 9999));
    assertEquals("172.28.9.1", conf.get(ConfUtils.addKeySuffixes(OZONE_SCM_DATANODE_BIND_HOST_KEY, scmServiceId, "scm1")));
    assertEquals("localhost:" + port++, conf.get(ConfUtils.addKeySuffixes(OZONE_SCM_HTTP_ADDRESS_KEY, scmServiceId, "scm1")));
    assertEquals("172.28.9.1", conf.get(ConfUtils.addKeySuffixes(OZONE_SCM_HTTP_BIND_HOST_KEY, scmServiceId, "scm1")));
    assertEquals("localhost", conf.get(ConfUtils.addKeySuffixes(OZONE_SCM_ADDRESS_KEY, scmServiceId, "scm1")));
    assertEquals("/var/scm-metadata1", conf.get(ConfUtils.addKeySuffixes(OZONE_SCM_DB_DIRS, scmServiceId, "scm1")));
    assertEquals(port++, conf.getInt(ConfUtils.addKeySuffixes(OZONE_SCM_RATIS_PORT_KEY, scmServiceId, "scm1"), 9999));
    final ScmRatisServerConfig scmRatisConfig = conf.getObject(ScmRatisServerConfig.class);
    assertEquals(0, scmRatisConfig.getLogAppenderWaitTimeMin(), "getLogAppenderWaitTimeMin");
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, tempDir.getPath());
    final RaftProperties p = RatisUtil.newRaftProperties(conf);
    final TimeDuration t = RaftServerConfigKeys.Log.Appender.waitTimeMin(p);
    assertEquals(TimeDuration.ZERO, t, RaftServerConfigKeys.Log.Appender.WAIT_TIME_MIN_KEY);
}

