    conf.set(OZONE_SCM_GRPC_PORT_KEY, "10001");
    conf.set(OZONE_SCM_BLOCK_CLIENT_PORT_KEY, "9896");
    conf.set(OZONE_SCM_CLIENT_PORT_KEY, "9897");
    conf.set(OZONE_SCM_DATANODE_PORT_KEY, "9898");
    conf.set(OZONE_SCM_SECURITY_SERVICE_PORT_KEY, "9899");
    SCMStorageConfig scmStorageConfig = mock(SCMStorageConfig.class);
    when(scmStorageConfig.getState()).thenReturn(Storage.StorageState.NOT_INITIALIZED);
    SCMHANodeDetails scmhaNodeDetails = SCMHANodeDetails.loadSCMHAConfig(conf, scmStorageConfig);
    assertEquals("10000", conf.get(OZONE_SCM_RATIS_PORT_KEY));
    assertEquals("10001", conf.get(OZONE_SCM_GRPC_PORT_KEY));
    InetSocketAddress clientAddress = NetUtils.createSocketAddr("0.0.0.0", 9897);
    InetSocketAddress blockAddress = NetUtils.createSocketAddr("0.0.0.0", 9896);
    InetSocketAddress datanodeAddress = NetUtils.createSocketAddr("0.0.0.0", 9898);
    assertEquals(clientAddress, scmhaNodeDetails.getLocalNodeDetails().getClientProtocolServerAddress());
    assertEquals(blockAddress, scmhaNodeDetails.getLocalNodeDetails().getBlockProtocolServerAddress());
    assertEquals(datanodeAddress, scmhaNodeDetails.getLocalNodeDetails().getDatanodeProtocolServerAddress());
    assertEquals(10000, scmhaNodeDetails.getLocalNodeDetails().getRatisPort());
    assertEquals(10001, scmhaNodeDetails.getLocalNodeDetails().getGrpcPort());
    for (SCMNodeDetails peer : scmhaNodeDetails.getPeerNodeDetails()) {
        assertEquals(clientAddress, peer.getClientProtocolServerAddress());
        assertEquals(blockAddress, peer.getBlockProtocolServerAddress());
        assertEquals(datanodeAddress, peer.getDatanodeProtocolServerAddress());
        assertEquals(10000, peer.getRatisPort());
        assertEquals(10001, peer.getGrpcPort());
    }
    // Security protocol address is not set in SCMHANode Details.
    // Check conf is properly set with expected port.
    assertEquals(NetUtils.createSocketAddr("0.0.0.0", 9899), HddsServerUtil.getScmSecurityInetAddress(conf));
}

