/**
 * Generate a list of random DNs and return the list. A total of 11 DNs will
 * be generated and registered with the node manager. Index 0 and 10 will
 * have the same IP and host and the rest will have unique IPs and Hosts.
 * The DN at index 10, has 3 hard coded ports of 3456, 4567, 5678. All other
 * DNs will have ports set to 0.
 * @return The list of DatanodeDetails Generated
 */
private List<DatanodeDetails> generateDatanodes() {
    List<DatanodeDetails> dns = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
        dns.add(dn);
        nodeManager.register(dn, null, null);
    }
    // We have 10 random DNs, we want to create another one that is on the same
    // host as some of the others, but with a different port
    DatanodeDetails multiDn = dns.get(0);
    DatanodeDetails.Builder builder = DatanodeDetails.newBuilder();
    builder.setUuid(UUID.randomUUID()).setHostName(multiDn.getHostName()).setIpAddress(multiDn.getIpAddress()).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.STANDALONE, 3456)).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.RATIS, 4567)).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.REST, 5678)).setNetworkLocation(multiDn.getNetworkLocation());
    DatanodeDetails dn = builder.build();
    dns.add(dn);
    nodeManager.register(dn, null, null);
    // Now add another DN with the same host and IP as dns(9), and with the
    // same port.
    DatanodeDetails duplicatePorts = dns.get(9);
    builder = DatanodeDetails.newBuilder();
    builder.setUuid(UUID.randomUUID()).setHostName(duplicatePorts.getHostName()).setIpAddress(duplicatePorts.getIpAddress()).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.STANDALONE, duplicatePorts.getPort(DatanodeDetails.Port.Name.STANDALONE).getValue())).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.RATIS, duplicatePorts.getPort(DatanodeDetails.Port.Name.RATIS).getValue())).addPort(DatanodeDetails.newPort(DatanodeDetails.Port.Name.REST, duplicatePorts.getPort(DatanodeDetails.Port.Name.REST).getValue())).setNetworkLocation(multiDn.getNetworkLocation());
    dn = builder.build();
    dns.add(dn);
    nodeManager.register(dn, null, null);
    return dns;
}

