@Test
public void testDatanodeIsInvalidInCaseOfIncreasingCommittedBytes() {
    NodeManager nodeMngr = mock(NodeManager.class);
    UUID datanodeUuid = UUID.randomUUID();
    DummyPlacementPolicy placementPolicy = new DummyPlacementPolicy(nodeMngr, conf, 1);
    DatanodeDetails datanodeDetails = mock(DatanodeDetails.class);
    when(datanodeDetails.getUuid()).thenReturn(datanodeUuid);
    DatanodeInfo datanodeInfo = mock(DatanodeInfo.class);
    NodeStatus nodeStatus = mock(NodeStatus.class);
    when(nodeStatus.isNodeWritable()).thenReturn(true);
    when(datanodeInfo.getNodeStatus()).thenReturn(nodeStatus);
    when(nodeMngr.getNodeByUuid(eq(datanodeUuid))).thenReturn(datanodeInfo);
    // capacity = 200000, used = 90000, remaining = 101000, committed = 500
    StorageContainerDatanodeProtocolProtos.StorageReportProto storageReport1 = HddsTestUtils.createStorageReport(UUID.randomUUID(), "/data/hdds", 200000, 90000, 101000, DISK).toBuilder().setCommitted(500).setFreeSpaceToSpare(10000).build();
    // capacity = 200000, used = 90000, remaining = 101000, committed = 1000
    StorageContainerDatanodeProtocolProtos.StorageReportProto storageReport2 = HddsTestUtils.createStorageReport(UUID.randomUUID(), "/data/hdds", 200000, 90000, 101000, DISK).toBuilder().setCommitted(1000).setFreeSpaceToSpare(100000).build();
    StorageContainerDatanodeProtocolProtos.MetadataStorageReportProto metaReport = HddsTestUtils.createMetadataStorageReport("/data/metadata", 200);
    when(datanodeInfo.getStorageReports()).thenReturn(Collections.singletonList(storageReport1)).thenReturn(Collections.singletonList(storageReport2));
    when(datanodeInfo.getMetadataStorageReports()).thenReturn(Collections.singletonList(metaReport));
    // 500 committed bytes:
    //
    //   101000       500
    //     |           |
    // (remaining - committed) > Math.max(4000, freeSpaceToSpare)
    //                                                    |
    //                                                  100000
    //
    // Summary: 101000 - 500 > 100000 == true
    assertTrue(placementPolicy.isValidNode(datanodeDetails, 100, 4000));
    // 1000 committed bytes:
    // Summary: 101000 - 1000 > 100000 == false
    assertFalse(placementPolicy.isValidNode(datanodeDetails, 100, 4000));
}

