    assertEquals(10.00, json.get(0).get("ozoneUsedPercent").doubleValue(), 0.001);
    assertEquals(80.00, json.get(0).get("remainingPercent").doubleValue(), 0.001);
    assertEquals(5, json.get(0).get("containerCount").longValue());
}

