@Test
public void testReadAgainstLargeBlockGroup() throws IOException {
    int dataBlocks = 10;
    int parityBlocks = 4;
    ECReplicationConfig ec10And4RepConfig = new ECReplicationConfig(dataBlocks, parityBlocks, ECReplicationConfig.EcCodec.RS, (int) (1 * MB));
    // default blockSize of 256MB with EC 10+4 makes a large block group
    long blockSize = 256 * MB;
    long blockLength = dataBlocks * blockSize;
    OmKeyInfo keyInfo = createOmKeyInfo(ec10And4RepConfig, dataBlocks + parityBlocks, blockLength);
    BlockExtendedInputStream blockInputStream = new ECStreamTestUtil.TestBlockInputStream(new BlockID(1, 1), blockLength, ByteBuffer.allocate(100));
    BlockInputStreamFactory mockStreamFactory = mock(BlockInputStreamFactory.class);
    when(mockStreamFactory.create(any(), any(), any(), any(), any(), any(), any())).thenReturn(blockInputStream);
    OzoneClientConfig clientConfig = conf.getObject(OzoneClientConfig.class);
    clientConfig.setChecksumVerify(true);
    try (LengthInputStream kis = KeyInputStream.getFromOmKeyInfo(keyInfo, null, null, mockStreamFactory, clientConfig)) {
        byte[] buf = new byte[100];
        int readBytes = kis.read(buf, 0, 100);
        assertEquals(100, readBytes);
    }
}

