@ParameterizedTest(name = "Ozone security enabled: {0}")
@ValueSource(booleans = { false, true })
public void testCaching(boolean securityEnabled) throws IOException {
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setBoolean(OZONE_SECURITY_ENABLED_KEY, securityEnabled);
    String metaDir = GenericTestUtils.getTempPath(TestXceiverClientManager.class.getName() + UUID.randomUUID());
    conf.set(HDDS_METADATA_DIR_NAME, metaDir);
    ClientTrustManager trustManager = mock(ClientTrustManager.class);
    try (XceiverClientManager clientManager = new XceiverClientManager(conf, conf.getObject(ScmClientConfig.class), trustManager)) {
        ContainerWithPipeline container1 = storageContainerLocationClient.allocateContainer(SCMTestUtils.getReplicationType(conf), HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE);
        XceiverClientSpi client1 = clientManager.acquireClient(container1.getPipeline());
        assertEquals(1, client1.getRefcount());
        ContainerWithPipeline container2 = storageContainerLocationClient.allocateContainer(SCMTestUtils.getReplicationType(conf), HddsProtos.ReplicationFactor.THREE, OzoneConsts.OZONE);
        XceiverClientSpi client2 = clientManager.acquireClient(container2.getPipeline());
        assertEquals(1, client2.getRefcount());
        XceiverClientSpi client3 = clientManager.acquireClient(container1.getPipeline());
        assertEquals(2, client3.getRefcount());
        assertEquals(2, client1.getRefcount());
        assertEquals(client1, client3);
        clientManager.releaseClient(client1, true);
        clientManager.releaseClient(client2, true);
        clientManager.releaseClient(client3, true);
        assertEquals(0, clientManager.getClientCache().size());
    }
}

@Test
void testGetKeyProvider() throws Exception {
    KeyProvider kp1 = store.getKeyProvider();
    KeyProvider kpSpy = spy(kp1);
    assertNotEquals(kpSpy, kp1);
    Cache<URI, KeyProvider> cacheSpy = ((RpcClient) store.getClientProxy()).getKeyProviderCache();
    cacheSpy.put(store.getKeyProviderUri(), kpSpy);
    KeyProvider kp2 = store.getKeyProvider();
    assertEquals(kpSpy, kp2);
    // Verify the spied key provider is closed upon ozone client close
    ozClient.close();
    verify(kpSpy).close();
    KeyProvider kp3 = ozClient.getObjectStore().getKeyProvider();
    assertNotEquals(kp3, kpSpy);
    reInitClient();
}

