private void setupCluster() throws Exception {
    cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(1).build();
    cluster.waitForClusterToBeReady();
    omMetrics = cluster.getOzoneManager().getMetrics();
    omDbCheckpointServletMock = mock(OMDBCheckpointServlet.class);
    BootstrapStateHandler.Lock lock = new OMDBCheckpointServlet.Lock(cluster.getOzoneManager());
    doCallRealMethod().when(omDbCheckpointServletMock).init();
    assertNull(doCallRealMethod().when(omDbCheckpointServletMock).getDbStore());
    requestMock = mock(HttpServletRequest.class);
    // Return current user short name when asked
    when(requestMock.getRemoteUser()).thenReturn(UserGroupInformation.getCurrentUser().getShortUserName());
    responseMock = mock(HttpServletResponse.class);
    ServletContext servletContextMock = mock(ServletContext.class);
    when(omDbCheckpointServletMock.getServletContext()).thenReturn(servletContextMock);
    when(servletContextMock.getAttribute(OzoneConsts.OM_CONTEXT_ATTRIBUTE)).thenReturn(cluster.getOzoneManager());
    when(requestMock.getParameter(OZONE_DB_CHECKPOINT_REQUEST_FLUSH)).thenReturn("true");
    doCallRealMethod().when(omDbCheckpointServletMock).doGet(requestMock, responseMock);
    doCallRealMethod().when(omDbCheckpointServletMock).doPost(requestMock, responseMock);
    doCallRealMethod().when(omDbCheckpointServletMock).writeDbDataToStream(any(), any(), any(), any(), any(), any());
    when(omDbCheckpointServletMock.getBootstrapStateLock()).thenReturn(lock);
    doCallRealMethod().when(omDbCheckpointServletMock).getCheckpoint(any(), anyBoolean());
}

