    assertEquals(initialCheckpointSet, finalCheckpointSet);
    String shortSnapshotLocation = truncateFileName(metaDirLength, Paths.get(snapshotDirName));
    String shortSnapshotLocation2 = truncateFileName(metaDirLength, Paths.get(snapshotDirName2));
    String shortCompactionDirLocation = truncateFileName(metaDirLength, compactionDirPath);
    Set<String> finalFullSet = getFiles(Paths.get(testDirName, OM_SNAPSHOT_DIR), testDirLength);
    // Check each line in the hard link file.
    List<String> fabricatedLinkLines = new ArrayList<>();
    try (Stream<String> lines = Files.lines(Paths.get(newDbDirName, OM_HARDLINK_FILE))) {
        for (String line : lines.collect(Collectors.toList())) {
            assertFalse(line.contains("CURRENT"), "CURRENT file is not a hard link");
            if (line.contains(FABRICATED_FILE_NAME)) {
                fabricatedLinkLines.add(line);
            } else {
                checkLine(shortSnapshotLocation, shortSnapshotLocation2, line);
                // add links to the final set
                finalFullSet.add(line.split("\t")[0]);
            }
        }
    }
    Set<String> directories = Sets.newHashSet(shortSnapshotLocation, shortSnapshotLocation2, shortCompactionDirLocation);
    checkFabricatedLines(directories, fabricatedLinkLines, testDirName);
    Set<String> initialFullSet = getFiles(Paths.get(metaDir.toString(), OM_SNAPSHOT_DIR), metaDirLength);
    assertThat(finalFullSet).contains(expectedLogStr);
    assertThat(finalFullSet).contains(expectedSstStr);
    assertEquals(initialFullSet, finalFullSet, "expected snapshot files not found");
}

