public void testValidateAndUpdateEncryption() throws Exception {
    KeyProviderCryptoExtension.EncryptedKeyVersion eKV = KeyProviderCryptoExtension.EncryptedKeyVersion.createForDecryption("key1", "v1", new byte[0], new byte[0]);
    KeyProviderCryptoExtension mockKeyProvider = mock(KeyProviderCryptoExtension.class);
    when(mockKeyProvider.generateEncryptedKey(any())).thenReturn(eKV);
    when(ozoneManager.getKmsProvider()).thenReturn(mockKeyProvider);
    keyName = "test/" + keyName;
    OMRequest omRequest = createFileRequest(volumeName, bucketName, keyName, HddsProtos.ReplicationFactor.ONE, HddsProtos.ReplicationType.RATIS, false, true);
    // add volume and create bucket with bucket encryption key
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, omMetadataManager, OmBucketInfo.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setBucketLayout(getBucketLayout()).setBucketEncryptionKey(new BucketEncryptionKeyInfo.Builder().setKeyName("key1").setSuite(mock(CipherSuite.class)).setVersion(mock(CryptoProtocolVersion.class)).build()));
    OMFileCreateRequest omFileCreateRequest = getOMFileCreateRequest(omRequest);
    OMRequest modifiedOmRequest = omFileCreateRequest.preExecute(ozoneManager);
    OMFileCreateRequest omFileCreateRequestPreExecuted = getOMFileCreateRequest(modifiedOmRequest);
    OMClientResponse omClientResponse = omFileCreateRequestPreExecuted.validateAndUpdateCache(ozoneManager, 100L);
    assertEquals(OzoneManagerProtocolProtos.Status.OK, omClientResponse.getOMResponse().getStatus());
    assertTrue(omClientResponse.getOMResponse().getCreateFileResponse().getKeyInfo().hasFileEncryptionInfo());
    when(ozoneManager.getKmsProvider()).thenReturn(null);
}

