    OzoneManagerProtocolProtos.SnapshotInfo snapshotInfoProto = omClientResponse.getOMResponse().getRenameSnapshotResponse().getSnapshotInfo();
    assertEquals(bucketDataSize, snapshotInfoProto.getReferencedSize());
    assertEquals(bucketUsedBytes, snapshotInfoProto.getReferencedReplicatedSize());
    SnapshotInfo snapshotInfoOldProto = getFromProtobuf(snapshotInfoProto);
    String key2 = getTableKey(volumeName, bucketName, snapshotName2);
