    assertEquals(snapshotInfo.getSnapshotId(), snapshotInfoNewInCache.getSnapshotId());
    SnapshotInfo snapshotInfoOldInCache = omMetadataManager.getSnapshotInfoTable().get(key);
    assertNull(snapshotInfoOldInCache);
}

