private Table<String, OmDirectoryInfo> getMockedDirectoryInfoTable(String prefix, Map<Integer, List<Integer>> dirMap) throws IOException {
    Table<String, OmDirectoryInfo> dirInfos = mock(Table.class);
    when(dirInfos.iterator(anyString())).thenAnswer(i -> {
        int dirId = Integer.parseInt(((String) i.getArgument(0)).split(OM_KEY_PREFIX)[3]);
        Iterator<? extends Table.KeyValue<String, OmDirectoryInfo>> iterator = dirMap.getOrDefault(dirId, Collections.emptyList()).stream().map(children -> new Table.KeyValue<String, OmDirectoryInfo>() {

            @Override
            public String getKey() {
                return prefix + children + OM_KEY_PREFIX + "dir" + children;
            }

            @Override
            public OmDirectoryInfo getValue() {
                return OmDirectoryInfo.newBuilder().setName("dir" + children).setObjectID(children).build();
            }
        }).iterator();
        return new TableIterator<String, Table.KeyValue<String, OmDirectoryInfo>>() {

            @Override
            public boolean hasNext() {
                return iterator.hasNext();
            }

            @Override
            public Table.KeyValue<String, OmDirectoryInfo> next() {
                return iterator.next();
            }

            @Override
            public void close() {
            }

            @Override
            public void seekToFirst() {
            }

            @Override
            public void seekToLast() {
            }

            @Override
            public Table.KeyValue<String, OmDirectoryInfo> seek(String s) {
                return null;
            }

            @Override
            public void removeFromDB() {
            }
        };
    });
    return dirInfos;
}

