@Test
public void testGetSnapshotDiffReportHappyCase() throws Exception {
    SnapshotInfo fromSnapInfo = snapshotInfo;
    SnapshotInfo toSnapInfo = snapshotInfoList.get(0);
    Set<String> testDeltaFiles = new HashSet<>();
    SnapshotDiffManager spy = spy(snapshotDiffManager);
    doReturn(testDeltaFiles).when(spy).getDeltaFiles(any(OmSnapshot.class), any(OmSnapshot.class), anyList(), eq(fromSnapInfo), eq(toSnapInfo), eq(false), anyMap(), anyString());
    doReturn(testDeltaFiles).when(spy).getSSTFileListForSnapshot(any(OmSnapshot.class), anyList());
    doNothing().when(spy).addToObjectIdMap(eq(keyInfoTable), eq(keyInfoTable), any(), anyBoolean(), any(), any(), any(), any(), any(), anyMap());
    doNothing().when(spy).checkReportsIntegrity(any(), anyInt(), anyInt());
    doReturn(10L).when(spy).generateDiffReport(anyString(), any(), any(), any(), any(), any(), any(), any(), anyString(), anyString(), anyString(), anyString(), anyBoolean(), any(), any(), anyMap());
    doReturn(LEGACY).when(spy).getBucketLayout(VOLUME_NAME, BUCKET_NAME, omMetadataManager);
    spy.getSnapshotDiffReport(VOLUME_NAME, BUCKET_NAME, fromSnapInfo.getName(), toSnapInfo.getName(), 0, 1000, false, false);
    Thread.sleep(1000L);
    spy.getSnapshotDiffReport(VOLUME_NAME, BUCKET_NAME, fromSnapInfo.getName(), toSnapInfo.getName(), 0, 1000, false, false);
    SnapshotDiffJob snapDiffJob = getSnapshotDiffJobFromDb(fromSnapInfo, toSnapInfo);
    assertEquals(DONE, snapDiffJob.getStatus());
    assertEquals(10L, snapDiffJob.getTotalDiffEntries());
