@ParameterizedTest
@MethodSource("getContainerLocationsTestCases")
public void testGetContainerLocations(String testCaseName, Set<Long> prepopulatedIds, Set<Long> testContainerIds, boolean forceRefresh, Set<Long> expectedScmCallIds) throws IOException {
    Map<Long, ContainerWithPipeline> actualLocations = new HashMap<>();
    for (long containerId : prepopulatedIds) {
        ContainerWithPipeline pipeline = createPipeline(containerId);
        actualLocations.put(containerId, pipeline);
    }
    // pre population of the cache.
    when(containerLocationProtocol.getContainerWithPipelineBatch(eq(prepopulatedIds))).thenReturn(new ArrayList<>(actualLocations.values()));
    Map<Long, Pipeline> locations = scmClient.getContainerLocations(prepopulatedIds, false);
    locations.forEach((id, pipeline) -> {
        assertEquals(actualLocations.get(id).getPipeline(), pipeline);
    });
    verify(containerLocationProtocol, times(1)).getContainerWithPipelineBatch(prepopulatedIds);
    // consecutive call
    if (!expectedScmCallIds.isEmpty()) {
        List<ContainerWithPipeline> scmLocations = new ArrayList<>();
        for (long containerId : expectedScmCallIds) {
            ContainerWithPipeline pipeline = createPipeline(containerId);
            scmLocations.add(pipeline);
            actualLocations.put(containerId, pipeline);
        }
        when(containerLocationProtocol.getContainerWithPipelineBatch(eq(expectedScmCallIds))).thenReturn(scmLocations);
    }
    locations = scmClient.getContainerLocations(testContainerIds, forceRefresh);
    locations.forEach((id, pipeline) -> {
        assertEquals(actualLocations.get(id).getPipeline(), pipeline);
    });
    if (!expectedScmCallIds.isEmpty()) {
        verify(containerLocationProtocol, times(1)).getContainerWithPipelineBatch(expectedScmCallIds);
    }
}

