@Test
public void testGetContainerLocationsWithScmFailures() throws IOException {
    IOException ioException = new IOException("Exception");
    when(containerLocationProtocol.getContainerWithPipelineBatch(newHashSet(1L))).thenThrow(ioException);
    IOException actual = assertThrows(IOException.class, () -> scmClient.getContainerLocations(newHashSet(1L), false));
    assertEquals(ioException, actual);
    RuntimeException runtimeException = new IllegalStateException("Test");
    when(containerLocationProtocol.getContainerWithPipelineBatch(newHashSet(2L))).thenThrow(runtimeException);
    RuntimeException actualRt = assertThrows(RuntimeException.class, () -> scmClient.getContainerLocations(newHashSet(2L), false));
    assertEquals(runtimeException, actualRt.getCause());
}

