    // Validate a valid event for BucketTable
    assertTrue(eventValidator.isValidEvent(omMetadataManager.getBucketTable().getName(), mock(OmBucketInfo.class), "key1", PUT));
    // Validate a valid event for DeletedTable
    assertTrue(eventValidator.isValidEvent(omMetadataManager.getDeletedTable().getName(), mock(RepeatedOmKeyInfo.class), "key1", PUT));
    // Validate a valid event for Prefix table
    assertTrue(eventValidator.isValidEvent(omMetadataManager.getPrefixTable().getName(), mock(OmPrefixInfo.class), "key1", PUT));
    // Validate a valid event for SnapshotInfo table
    assertTrue(eventValidator.isValidEvent(omMetadataManager.getSnapshotInfoTable().getName(), mock(SnapshotInfo.class), "key1", PUT));
    // Verify that no log message is printed
    verify(logger, never()).warn(anyString());
}

@Test
public void testInvalidEvents() throws IOException {
    // Validate an invalid event for VolumeInfo table
    assertFalse(eventValidator.isValidEvent(omMetadataManager.getVolumeTable().getName(), "Invalid Object", "key1", PUT));
