private String initiateMultipartUpload(String key, Map<String, String> metadata) throws IOException, OS3Exception {
    MultivaluedMap<String, String> metadataHeaders = new MultivaluedHashMap<>();
    for (Map.Entry<String, String> entry : metadata.entrySet()) {
        metadataHeaders.computeIfAbsent(CUSTOM_METADATA_HEADER_PREFIX + entry.getKey(), k -> new ArrayList<>()).add(entry.getValue());
    }
    when(HEADERS.getRequestHeaders()).thenReturn(metadataHeaders);
    Response response = REST.initializeMultipartUpload(OzoneConsts.S3_BUCKET, key);
    MultipartUploadInitiateResponse multipartUploadInitiateResponse = (MultipartUploadInitiateResponse) response.getEntity();
    assertNotNull(multipartUploadInitiateResponse.getUploadID());
    String uploadID = multipartUploadInitiateResponse.getUploadID();
    assertEquals(200, response.getStatus());
    return uploadID;
}

